diff --git a/src/wireplumber/90-plasma-pa-default-nodes.conf b/src/wireplumber/90-plasma-pa-default-nodes.conf
new file mode 100644
index 00000000..250116ce
--- /dev/null
+++ b/src/wireplumber/90-plasma-pa-default-nodes.conf
@@ -0,0 +1,34 @@
+# Provides the node.switch-to-new-default-targets setting, which the Sound
+# settings page toggles, for WirePlumber versions that don't have it yet.
+
+wireplumber.settings.schema = {
+  node.switch-to-new-default-targets = {
+    name = "Switch to new default targets"
+    description = "Make a newly available audio/video input/output device the default when it has a higher priority than the current one"
+    type = "bool"
+    default = true
+  }
+}
+
+wireplumber.components = [
+  {
+    name = plasma-pa/find-current-default-node.lua, type = script/lua
+    provides = hooks.plasma-pa.find-current-default-node
+    requires = [ metadata.default ]
+  }
+]
+
+wireplumber.components.rules = [
+  {
+    matches = [
+      {
+        provides = "policy.default-nodes"
+      }
+    ]
+    actions = {
+      merge = {
+        wants = [ hooks.plasma-pa.find-current-default-node ]
+      }
+    }
+  }
+]
