diff --git a/src/wireplumber/find-current-default-node.lua b/src/wireplumber/find-current-default-node.lua
new file mode 100644
index 00000000..ac12b16f
--- /dev/null
+++ b/src/wireplumber/find-current-default-node.lua
@@ -0,0 +1,84 @@
+-- SPDX-License-Identifier: MIT
+-- SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+-- Provides node.switch-to-new-default-targets for WirePlumber versions that
+-- don't have it: keeps the current default node while it is available, so that
+-- a newly available node with a higher priority does not take over. Nodes
+-- selected by the user (default.configured.* and the stored past selections)
+-- still win, as they have a higher priority than this hook gives.
+
+log = Log.open_topic ("s-default-nodes")
+
+nutils = require ("node-utils")
+
+hook = SimpleEventHook {
+  name = "plasma-pa/find-current-default-node",
+  after = { "default-nodes/find-selected-default-node",
+            "default-nodes/find-stored-default-node" },
+  before = { "default-nodes/find-best-default-node" },
+  interests = {
+    EventInterest {
+      Constraint { "event.type", "=", "select-default-node" },
+    },
+  },
+  execute = function (event)
+    local available_nodes = event:get_data ("available-nodes")
+
+    available_nodes = available_nodes and available_nodes:parse ()
+    if not available_nodes then
+      return
+    end
+
+    local source = event:get_source ()
+    local props = event:get_properties ()
+    local def_node_type = props ["default-node.type"]
+    local metadata_om = source:call ("get-object-manager", "metadata")
+    local metadata = metadata_om:lookup { Constraint { "metadata.name", "=", "default" } }
+    local obj = metadata and metadata:find (0, "default." .. def_node_type)
+
+    if not obj then
+      return
+    end
+
+    local current_node = Json.Raw (obj):parse ().name
+
+    for _, node_props in ipairs (available_nodes) do
+      if node_props ["node.name"] == current_node then
+        -- a sink monitor is only the default source until a real source appears
+        if def_node_type == "audio.source" and
+            node_props ["media.class"] == "Audio/Sink" then
+          return
+        end
+
+        -- above any node priority, below the user's selections
+        local priority = nutils.get_session_priority (node_props) + 10000
+        local selected_prio = event:get_data ("selected-node-priority") or 0
+
+        if priority > selected_prio then
+          log:debug ("keeping current default node " .. current_node)
+          event:set_data ("selected-node-priority", priority)
+          event:set_data ("selected-node", current_node)
+        end
+
+        break
+      end
+    end
+  end
+}
+
+registered = false
+
+function toggleHook (switch_to_new)
+  if switch_to_new and registered then
+    hook:remove ()
+    registered = false
+  elseif not switch_to_new and not registered then
+    hook:register ()
+    registered = true
+  end
+end
+
+Settings.subscribe ("node.switch-to-new-default-targets", function ()
+  toggleHook (Settings.get_boolean ("node.switch-to-new-default-targets"))
+end)
+toggleHook (Settings.get_boolean ("node.switch-to-new-default-targets"))
diff --git a/src/wireplumbersetting.cpp b/src/wireplumbersetting.cpp
new file mode 100644
index 00000000..5e60d9b8
--- /dev/null
+++ b/src/wireplumbersetting.cpp
@@ -0,0 +1,97 @@
+// SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+// SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+#include "wireplumbersetting.h"
+
+#include <QProcess>
+
+#include "debug.h"
+
+using namespace Qt::StringLiterals;
+
+WirePlumberSetting::WirePlumberSetting(QObject *parent)
+    : QObject(parent)
+{
+}
+
+QString WirePlumberSetting::key() const
+{
+    return m_key;
+}
+
+void WirePlumberSetting::setKey(const QString &key)
+{
+    if (m_key == key) {
+        return;
+    }
+    m_key = key;
+    Q_EMIT keyChanged();
+    load();
+}
+
+bool WirePlumberSetting::isAvailable() const
+{
+    return m_available;
+}
+
+bool WirePlumberSetting::value() const
+{
+    return m_value;
+}
+
+void WirePlumberSetting::setValue(bool value)
+{
+    if (!m_available || m_value == value) {
+        return;
+    }
+    m_value = value;
+    Q_EMIT valueChanged();
+
+    auto wpctl = new QProcess(this);
+    connect(wpctl, &QProcess::finished, this, [this, wpctl](int exitCode, QProcess::ExitStatus exitStatus) {
+        wpctl->deleteLater();
+        if (exitStatus != QProcess::NormalExit || exitCode != 0) {
+            qCWarning(PLASMAPA) << "Failed to save WirePlumber setting" << m_key << wpctl->readAllStandardError();
+            load();
+        }
+    });
+    connect(wpctl, &QProcess::errorOccurred, this, [this, wpctl](QProcess::ProcessError error) {
+        if (error == QProcess::FailedToStart) {
+            qCWarning(PLASMAPA) << "Failed to save WirePlumber setting" << m_key << wpctl->errorString();
+            wpctl->deleteLater();
+            load();
+        }
+    });
+    wpctl->start(u"wpctl"_s, {u"settings"_s, u"--save"_s, m_key, value ? u"true"_s : u"false"_s});
+}
+
+void WirePlumberSetting::load()
+{
+    auto wpctl = new QProcess(this);
+    connect(wpctl, &QProcess::finished, this, [this, wpctl, key = m_key] {
+        wpctl->deleteLater();
+        if (key != m_key) {
+            return;
+        }
+        // Prints "Value: <json>", or a "not found" message for settings this WirePlumber doesn't have
+        const QString output = QString::fromUtf8(wpctl->readAllStandardOutput()).trimmed();
+        const bool available = output.startsWith("Value: "_L1);
+        const bool value = output == "Value: true"_L1;
+        if (m_value != value) {
+            m_value = value;
+            Q_EMIT valueChanged();
+        }
+        if (m_available != available) {
+            m_available = available;
+            Q_EMIT availableChanged();
+        }
+    });
+    connect(wpctl, &QProcess::errorOccurred, wpctl, [wpctl](QProcess::ProcessError error) {
+        if (error == QProcess::FailedToStart) {
+            wpctl->deleteLater();
+        }
+    });
+    wpctl->start(u"wpctl"_s, {u"settings"_s, m_key});
+}
+
+#include "moc_wireplumbersetting.cpp"
diff --git a/src/wireplumbersetting.h b/src/wireplumbersetting.h
new file mode 100644
index 00000000..adbcba7a
--- /dev/null
+++ b/src/wireplumbersetting.h
@@ -0,0 +1,37 @@
+// SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+// SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+#pragma once
+
+#include <QObject>
+#include <qqmlregistration.h>
+
+// A boolean WirePlumber setting, read and saved with wpctl
+class WirePlumberSetting : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    Q_PROPERTY(QString key READ key WRITE setKey NOTIFY keyChanged REQUIRED)
+    Q_PROPERTY(bool available READ isAvailable NOTIFY availableChanged)
+    Q_PROPERTY(bool value READ value WRITE setValue NOTIFY valueChanged)
+public:
+    explicit WirePlumberSetting(QObject *parent = nullptr);
+
+    [[nodiscard]] QString key() const;
+    void setKey(const QString &key);
+    [[nodiscard]] bool isAvailable() const;
+    [[nodiscard]] bool value() const;
+    void setValue(bool value);
+
+Q_SIGNALS:
+    void keyChanged();
+    void availableChanged();
+    void valueChanged();
+
+private:
+    void load();
+
+    QString m_key;
+    bool m_available = false;
+    bool m_value = false;
+};
